<?= $this->extend('layouts/app') ?><?= $this->section('content') ?>
<?php
$role = (string) session()->get('role');
$userId = (int) session()->get('user_id');
$canSubmit = in_array($role, ['manager', 'facilitator'], true);
$usedScheduleIds = array_map('intval', array_column($results, 'schedule_id'));
$availableSchedules = array_values(array_filter($schedules, static fn(array $schedule): bool => ! in_array((int) $schedule['id'], $usedScheduleIds, true) && $schedule['status'] !== 'cancelled'));
?>
<div class="page-head"><div><h1><?= esc($title) ?></h1><p><?= $resultType === 'match' ? 'Enter live match scores. Pending results can be corrected before validator acceptance.' : 'Enter judged scores; placements are calculated from submitted scores and become official only after validation.' ?></p></div><?php if ($canSubmit): ?><button class="btn primary" data-modal="result-modal" <?= !$availableSchedules ? 'disabled' : '' ?>>+ Encode Result</button><?php endif; ?></div>
<section class="panel"><div class="panel-head"><div><h2><?= $resultType === 'match' ? 'Match Bracket' : 'Judged Event Bracket' ?></h2><p>Schedules are grouped by round and horizontally scrollable.</p></div></div><?php $bracket = []; foreach ($schedules as $schedule) { $bracket[$schedule['round']][] = $schedule; } ?><div class="bracket-board"><?php foreach ($bracket as $round => $roundSchedules): ?><div class="bracket-stage"><h3><?= esc($round) ?></h3><?php foreach ($roundSchedules as $schedule): ?><article class="bracket-match"><b><?= esc($schedule['sport_name'].' · '.$schedule['category']) ?></b><span><?= $resultType === 'match' ? esc(($schedule['team_a_name'] ?? 'Open').' vs '.($schedule['team_b_name'] ?? 'Open')) : 'All participating teams' ?></span><small><?= esc(($schedule['location_name'] ?? '—').' · '.date('M j, g:i A', strtotime($schedule['match_date']))) ?></small><em><?= strtoupper(esc($schedule['status'])) ?></em></article><?php endforeach; ?></div><?php endforeach; ?><?php if (!$bracket): ?><div class="empty">No schedules available.</div><?php endif; ?></div></section>
<section class="panel"><div class="panel-head"><div><h2><?= $resultType === 'match' ? 'Match Schedules' : 'Judged Schedules' ?></h2><p>Detailed active-event schedule list.</p></div></div><div class="table-wrap"><table><thead><tr><th>Sport</th><th>Round</th><th>Location</th><th>Teams</th><th>Date</th><th>Status</th></tr></thead><tbody><?php foreach ($schedules as $schedule): ?><tr><td><b><?= esc($schedule['sport_name']) ?></b><small class="muted"><?= esc($schedule['category']) ?></small></td><td><?= esc($schedule['round']) ?></td><td><?= esc($schedule['location_name'] ?? '—') ?></td><td><?= $resultType === 'match' ? esc(($schedule['team_a_name'] ?? 'Open').' vs '.($schedule['team_b_name'] ?? 'Open')) : 'All participating teams' ?></td><td><?= esc(date('M j, g:i A', strtotime($schedule['match_date']))) ?></td><td><span class="badge neutral"><?= strtoupper(esc($schedule['status'])) ?></span></td></tr><?php endforeach; ?><?php if (!$schedules): ?><tr><td colspan="6" class="empty">No schedules available.</td></tr><?php endif; ?></tbody></table></div></section>
<section class="panel"><div class="panel-head"><div><h2><?= esc($title) ?></h2><p>Official and unofficial results are clearly separated by status.</p></div></div><div class="result-list">
<?php if (!$results): ?><div class="empty">No results have been submitted yet.</div><?php endif; ?>
<?php foreach ($results as $result): ?>
<?php
$canEditResult = $canSubmit && $result['status'] === 'pending' && ($role === 'manager' || (int) $result['submitted_by'] === $userId);
$entryByTeam = [];
foreach ($result['entries'] as $entry) { $entryByTeam[(int) $entry['team_id']] = $entry; }
?>
<article class="result-card"><div class="result-top"><div><b><?= esc($result['sport_name'].' · '.$result['category']) ?></b><span><?= esc($result['round']) ?> · <?= esc($result['location_name'] ?? '') ?></span></div><span class="badge <?= $result['status'] === 'validated' ? 'official' : 'unofficial' ?>"><?= $result['status'] === 'validated' ? 'OFFICIAL' : 'UNOFFICIAL' ?></span></div><div class="score-entries"><?php foreach ($result['entries'] as $entry): ?><div><span><?= esc($entry['team_name']) ?></span><strong><?= number_format((float) $entry['raw_score'], 2) ?></strong><?php if ($entry['placement']): ?><small>#<?= (int) $entry['placement'] ?> · <?= esc(format_points($entry['allocated_points'])) ?> pts</small><?php endif; ?></div><?php endforeach; ?></div><?php if (trim((string) $result['notes']) !== ''): ?><p class="result-notes"><?= esc($result['notes']) ?></p><?php endif; ?><div class="result-foot"><small>Submitted by <?= esc($result['submitted_by_name'] ?? 'System') ?> · <?= esc(date('M j, g:i A', strtotime($result['submitted_at']))) ?></small><div class="result-actions"><?php if ($role === 'validator' && $result['status'] === 'pending'): ?><form method="post" action="<?= site_url('results/'.$result['id'].'/validate') ?>" class="validate-form"><?= csrf_field() ?><label class="check compact-check"><input type="checkbox" name="confirmed_sheet" value="1" required> Compared with official score sheet/form</label><button class="btn tiny primary">Validate as Official</button></form><?php elseif ($result['status'] === 'validated'): ?><small>Validated by <?= esc($result['validated_by_name'] ?? 'Validator') ?></small><?php elseif ($canEditResult): ?><button class="btn tiny" data-modal="result-edit-<?= (int) $result['id'] ?>">Edit</button><form method="post" action="<?= site_url('results/'.$result['id'].'/delete') ?>" data-confirm="Delete this unofficial result? The schedule will return to scheduled status."><?= csrf_field() ?><button class="btn tiny danger">Delete</button></form><?php endif; ?></div></div></article>
<?php if ($canEditResult): ?><dialog id="result-edit-<?= (int) $result['id'] ?>"><form method="post" action="<?= site_url('results/'.$result['id'].'/update') ?>" class="modal-card wide"><?= csrf_field() ?><input type="hidden" name="schedule_id" value="<?= (int) $result['schedule_id'] ?>"><div class="modal-head"><h2>Edit Unofficial Result</h2><button type="button" data-close aria-label="Close">×</button></div><div class="form-note result-context"><?= esc($result['sport_name'].' · '.$result['round'].' · '.date('M j, g:i A', strtotime($result['match_date']))) ?></div><?php if ($resultType === 'match'): ?><div class="form-grid"><label><?= esc($entryByTeam[(int) $result['team_a_id']]['team_name'] ?? 'Team A') ?> Score<input type="number" step="0.01" min="0" max="99999999.99" name="team_a_score" required value="<?= esc($entryByTeam[(int) $result['team_a_id']]['raw_score'] ?? '') ?>"></label><label><?= esc($entryByTeam[(int) $result['team_b_id']]['team_name'] ?? 'Team B') ?> Score<input type="number" step="0.01" min="0" max="99999999.99" name="team_b_score" required value="<?= esc($entryByTeam[(int) $result['team_b_id']]['raw_score'] ?? '') ?>"></label></div><?php else: ?><div class="judged-grid"><?php foreach ($teams as $team): ?><label><?= esc($team['name']) ?><input type="number" step="0.01" min="0" max="99999999.99" name="judged[<?= (int) $team['id'] ?>]" value="<?= esc($entryByTeam[(int) $team['id']]['raw_score'] ?? '') ?>" placeholder="Score"></label><?php endforeach; ?></div><?php endif; ?><label>Notes<textarea name="notes" rows="3" placeholder="Optional notes from the score sheet"><?= esc($result['notes']) ?></textarea></label><div class="warning-box">Editing keeps this result <b>UNOFFICIAL</b> and awaiting validator approval.</div><button class="btn primary full">Save Result Changes</button></form></dialog><?php endif; ?>
<?php endforeach; ?>
</div></section>
<?php if ($canSubmit): ?><dialog id="result-modal"><form method="post" action="<?= site_url('results') ?>" class="modal-card wide"><?= csrf_field() ?><div class="modal-head"><h2>Encode <?= $resultType === 'match' ? 'Match' : 'Judged' ?> Result</h2><button type="button" data-close aria-label="Close">×</button></div><label>Schedule<select name="schedule_id" required><option value="">Select schedule</option><?php foreach ($availableSchedules as $schedule): ?><option value="<?= (int) $schedule['id'] ?>"><?= esc($schedule['sport_name'].' · '.$schedule['round'].' · '.date('M j g:i A', strtotime($schedule['match_date']))) ?></option><?php endforeach; ?></select></label><?php if ($resultType === 'match'): ?><div class="form-grid"><label>Team A Score<input type="number" step="0.01" min="0" max="99999999.99" name="team_a_score" required></label><label>Team B Score<input type="number" step="0.01" min="0" max="99999999.99" name="team_b_score" required></label></div><?php else: ?><div class="judged-grid"><?php foreach ($teams as $team): ?><label><?= esc($team['name']) ?><input type="number" step="0.01" min="0" max="99999999.99" name="judged[<?= (int) $team['id'] ?>]" placeholder="Score"></label><?php endforeach; ?></div><?php endif; ?><label>Notes<textarea name="notes" rows="3" placeholder="Optional notes from the score sheet"></textarea></label><div class="warning-box">This submission is published immediately as <b>UNOFFICIAL</b>. A validator must compare it with the actual score sheet/form before it becomes official.</div><button class="btn primary full">Submit Unofficial Result</button></form></dialog><?php endif; ?>
<?= $this->endSection() ?>
